@DataJpaTest
@ActiveProfiles("test")
class ProductRepositoryTest {

    @Autowired
    private ProductRepository productRepository;

    @DisplayName("상품 번호 목록으로 조회하면 해당 상품들만 나온다")
    @Test
    void findAllByProductNumberIn() {
        // given
        productRepository.saveAll(List.of(
                createProduct("001", SELLING, "아메리카노", 4000),
                createProduct("002", HOLD, "카페라떼", 4500),
                createProduct("003", STOP_SELLING, "팥빙수", 7000)));

        // when
        List<Product> products =
                productRepository.findAllByProductNumberIn(List.of("001", "002"));

        // then
        assertThat(products).hasSize(2)
                .extracting("productNumber", "name", "sellingStatus")
                .containsExactlyInAnyOrder(
                        tuple("001", "아메리카노", SELLING),
                        tuple("002", "카페라떼", HOLD));
    }
}

class OrderControllerTest extends ControllerTestSupport {

    @DisplayName("주문 시 상품 번호는 1개 이상이어야 한다")
    @Test
    void createOrderWithEmptyProductNumbers() throws Exception {
        // given
        OrderCreateRequest request = OrderCreateRequest.builder()
                .productNumbers(List.of())
                .build();

        // when & then
        mockMvc.perform(post("/api/v1/orders/new")
                        .content(objectMapper.writeValueAsString(request))
                        .contentType(APPLICATION_JSON))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.message").value("상품 번호 리스트는 필수입니다."));

        verify(orderService, never()).createOrder(any(), any());
    }
}
